def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_my, last_opp = history[-1]

    # Exploit mode: if we defected and opponent cooperated, keep defecting
    if last_my == 'D' and last_opp == 'C':
        return 'D'

    opp_defects = 0
    my_defects = 0
    exploited = False
    for me, op in history:
        if op == 'D':
            opp_defects += 1
        if me == 'D':
            my_defects += 1
        if me == 'D' and op == 'C':
            exploited = True

    # ALLC detection / exploitation
    if opp_defects == 0:
        if my_defects > 0:
            return 'D'
        if n >= 15:
            return 'D'
        return 'C'

    # Compute runs
    run_my_d = 0
    for me, op in reversed(history):
        if me == 'D':
            run_my_d += 1
        else:
            break
    run_opp_d = 0
    for me, op in reversed(history):
        if op == 'D':
            run_opp_d += 1
        else:
            break
    run_my_c = 0
    for me, op in reversed(history):
        if me == 'C':
            run_my_c += 1
        else:
            break
    run_opp_c = 0
    for me, op in reversed(history):
        if op == 'C':
            run_opp_c += 1
        else:
            break

    # If opponent has defected before, but we've had a long cooperation streak,
    # and we haven't tried to exploit yet, try to defect to test/exploit.
    if opp_defects > 0 and not exploited and run_opp_c >= 5 and run_my_c >= 5 and n < 95:
        return 'D'

    if last_opp == 'D':
        if last_my == 'C':
            if run_my_c == 1:
                return 'C'
            else:
                return 'D'
        else:
            if run_my_d >= 2 and run_opp_d >= 2 and run_opp_d <= 5:
                return 'C'
            if opp_defects <= 2:
                return 'C'
            return 'D'
    else:
        return 'C'
